<template><section class="view on"><PageHead title="社区帖子" sub="审核、精选与下架都会留下状态记录"><div class="toolbar"><button v-for="s in states" :key="s.value" class="chip" :class="{ on: status === s.value }" type="button" @click="change(s.value)">{{ s.label }}</button></div></PageHead><div class="sheet"><table><thead><tr><th>帖子</th><th>作者</th><th>互动</th><th>状态</th><th>时间</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.postId"><td><strong>{{ row.title }}</strong><div class="muted">{{ row.content }}</div></td><td>{{ row.author?.nickname || row.author?.userId || '—' }}</td><td>赞 {{ row.likeCount }} · 评 {{ row.commentCount }} · 藏 {{ row.collectCount }}</td><td><span class="pill" :class="row.status === 'published' || row.status === 'featured' ? 'ok' : row.status === 'review' ? 'wait' : 'bad'">{{ row.status }}</span></td><td>{{ row.createdAt }}</td><td><button v-if="row.status === 'review' || row.status === 'down'" class="linkish" type="button" @click="setStatus(row, 'published')">通过</button><button v-if="row.status === 'published'" class="linkish" type="button" @click="setStatus(row, 'featured')">精选</button><button v-if="row.status !== 'down'" class="linkish" type="button" @click="setStatus(row, 'down')">下架</button></td></tr><tr v-if="!loading && !rows.length"><td colspan="6"><div class="empty">暂无帖子</div></td></tr><tr v-if="loading"><td colspan="6"><div class="empty">正在读取…</div></td></tr></tbody></table></div></section></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import PageHead from '@/components/kitchen/PageHead.vue'; import { listAdminPosts, updateAdminPostStatus, type AdminPost } from '@/api/social'; import { toast } from '@/utils/toast'; const rows=ref<AdminPost[]>([]); const loading=ref(false); const status=ref(''); const states=[{value:'',label:'全部'},{value:'review',label:'待审核'},{value:'published',label:'已发布'},{value:'featured',label:'精选'},{value:'down',label:'已下架'}]; async function load(){loading.value=true;try{rows.value=(await listAdminPosts({status:status.value||undefined,page:1,pageSize:100})).data?.list||[]}finally{loading.value=false}} function change(value:string){status.value=value;load()} async function setStatus(row:AdminPost,toStatus:string){try{await updateAdminPostStatus(row.postId,{toStatus,reason:'运营审核'});toast('状态已更新');load()}catch {}} onMounted(load)
</script>
